reference_solution:
def car_fleet_count(target, position, speed):
 fleets=[]
 for p,v in sorted(zip(position,speed),reverse=True):
  time=(target-p)/v
  if not fleets or time>fleets[-1]:fleets.append(time)
 return len(fleets)

